// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

library UpgradeLib {
    function verifyTimelock(address timelock) internal view {
        require(msg.sender == timelock, "caller not timelock");
    }
}

abstract contract BaseUpgrade {
    address public timelock;
    address public implementation;
}

contract ConcreteUpgrade is BaseUpgrade {
    using UpgradeLib for address;

    function upgradeTo(address newImpl) external {
        timelock.verifyTimelock();
        implementation = newImpl;
    }
}
